# %% [markdown]
# ## 3. Exercise 2 — `tainted_components`: how far does outside text travel?
#
# The entry points are not the whole story. Text that enters at the fetcher is read by a research agent,
# which passes a summary to the orchestrator, which writes to memory, calls tools and shows a person a
# summary. Everything downstream of an untrusted source is **tainted**: not necessarily compromised, but
# reachable by whoever controls that source.
#
# Write `tainted_components(components, flows)`. The **sources** are the components at trust 0. A flow
# tagged `"content"` carries its source's text to its destination; a flow without that tag (an approval
# signal, say) carries none. Return the sorted list of component names that are the destination of a
# content flow from a source or from an already-tainted component. A source is in the list only if some
# content flow from a tainted or source component reaches it. The architecture has cycles: do not loop.
#
# <details><summary>💡 Hint 1 — what to think about</summary>
#
# One step from a source is not enough: what the first step reaches can pass the text on. Think of a set
# that grows until a whole pass over the flows adds nothing, and of what stops that from running for ever
# when two components send text to each other.
#
# </details>
# <details><summary>💡 Hint 2 — the approach in words</summary>
#
# Keep a set of names that already carry outside text (start it with the sources) and a separate set of
# names reached. Repeat over the content flows: when a flow's source carries text, its destination is reached
# and now carries text too. Stop when a pass changes nothing. Return the reached names sorted.
#
# </details>

# %%
def tainted_components(components, flows):
    """Every component that text from a trust-0 source can reach through content flows.

    Args:
        components: dict, name -> {"trust": int, "tags": frozenset}. The sources are those with trust 0.
        flows: list of dicts with "id", "src", "dst", "tags". Only flows tagged "content" carry text.

    A flow that names an unknown component raises ``ValueError``. Cycles are normal.

    Returns:
        A sorted list of names: those that are the destination of a content flow whose source is a
        source or already tainted. A source appears only if such a flow reaches it.

    Example:
        >>> comps = {"s": {"trust": 0, "tags": frozenset()}, "a": {"trust": 2, "tags": frozenset()},
        ...          "b": {"trust": 2, "tags": frozenset()}}
        >>> fl = [{"id": "1", "src": "s", "dst": "a", "tags": frozenset({"content"})},
        ...       {"id": "2", "src": "a", "dst": "b", "tags": frozenset({"content"})}]
        >>> tainted_components(comps, fl)
        ['a', 'b']
    """
    # YOUR CODE HERE
    raise NotImplementedError


def _check_tainted_components() -> None:
    n = frozenset
    comps = {"s": {"trust": 0, "tags": n()}, "zz": {"trust": 2, "tags": n()}, "aa": {"trust": 2, "tags": n()},
             "c": {"trust": 2, "tags": n()}, "t": {"trust": 1, "tags": n()}, "e": {"trust": 2, "tags": n()},
             "w": {"trust": 0, "tags": n()}}
    fl = [{"id": "3", "src": "aa", "dst": "zz", "tags": n({"content"})},
          {"id": "2", "src": "zz", "dst": "aa", "tags": n({"content"})},
          {"id": "1", "src": "s", "dst": "zz", "tags": n({"content"})},
          {"id": "4", "src": "aa", "dst": "c", "tags": n({"approval"})},
          {"id": "5", "src": "t", "dst": "e", "tags": n({"content"})},
          {"id": "6", "src": "zz", "dst": "s", "tags": n({"content"})}]
    got = tainted_components(comps, fl)
    assert isinstance(got, list) and got == ["aa", "s", "zz"], (
        f"got {got}. Follow content flows as far as they go, however the flows are listed (aa to zz is listed before s to zz) and "
        "round the cycle; do not follow a flow that is not tagged content (aa to c); only trust-0 components are sources (t, at "
        "trust 1, is not); a source is listed only if a tainted component sends it text (s yes, w no); return a sorted list.")
    print("exercise 2 looks right")


_try("exercise 2", _check_tainted_components)

# %%
def _one_hop(components, flows):
    """Given, for comparison: only the destinations of content flows that start at a source."""
    sources = {n for n, c in components.items() if c["trust"] == 0}
    return sorted({f["dst"] for f in flows if "content" in f["tags"] and f["src"] in sources})


def _show_taint() -> None:
    check_architecture(COMPONENTS, FLOWS)
    full, near = tainted_components(COMPONENTS, FLOWS), _one_hop(COMPONENTS, FLOWS)
    print(f"text from outside reaches {len(full)} of {len(COMPONENTS)} components: {', '.join(full)}")
    print(f"flows leaving a source reach only {len(near)}: {', '.join(near)}")
    missed = [n for n in full if n not in near]
    print(f"{len(missed)} components a one-step view misses, among them {', '.join(n for n in missed if COMPONENTS[n]['trust'] == 3) or 'no person'} (trust 3, a person)")
    untouched = [n for n in COMPONENTS if n not in full]
    print(f"not reached: {', '.join(untouched)}")


_try("taint", _show_taint, needs=("exercise 2",))

