    chat_flows = [_f("c1", "user", "assistant", "content"), _f("c2", "web", "fetch", "content"), _f("c3", "fetch", "assistant", "content")]
    chat_reg = risk_register(chat, chat_flows, tainted_components(chat, chat_flows), RULES)
    print(f"a chat assistant with one fetcher and nothing else is exposed to {sum(bool(v) for v in chat_reg.values())} of {len(ASI_IDS)} categories "
          f"({', '.join(a for a, v in chat_reg.items() if v) or 'none'}); the rules key on capabilities, not on the word 'agent'")
    near = risk_register(COMPONENTS, FLOWS, _one_hop(COMPONENTS, FLOWS), RULES)
    lost = sum(len(v) for v in reg.values()) - sum(len(v) for v in near.values())
    print(f"with the one-step view of taint from section 3, {lost} exposures drop out of the register")


