# %% [markdown]
# ## 5. Exercise 4 — `mitigation_checklist`: from exposures to work items
#
# A register says what is exposed. A **checklist** says what must be true about each exposed item. The
# next cell is a small catalogue, this course's own, of mitigations for each category. One mitigation can
# answer several categories (scoped credentials limit both a misused tool and an abused identity).
#
# Write `mitigation_checklist(register, controls)`: one row `(item, mitigation, categories)` for every
# distinct `(item, mitigation)` pair the register calls for, where `categories` is the sorted **tuple** of
# every category that asks for it. Sort the rows by item, then mitigation. A category that has exposed items but
# no entry in `controls` raises `ValueError` naming it: a risk with no listed mitigation must not
# vanish from the list in silence. A key present with an empty list *is* an entry: it adds no rows and does not raise.

# %%
CONTROLS = {
    "ASI01": ["untrusted-content-marked", "goal-lock-check"],
    "ASI02": ["tool-allowlist", "argument-validation", "human-approval-on-irreversible", "scoped-credentials"],
    "ASI03": ["scoped-credentials", "short-lived-tokens"],
    "ASI04": ["pinned-tool-versions", "tool-description-review"],
    "ASI05": ["sandboxed-execution", "human-approval-on-irreversible"],
    "ASI06": ["memory-write-validation", "memory-provenance-tags", "action-logging"],
    "ASI07": ["message-authentication"],
    "ASI08": ["step-and-spend-limit", "action-logging"],
    "ASI09": ["approval-shows-raw-source", "human-approval-on-irreversible"],
    "ASI10": ["kill-switch", "action-logging", "step-and-spend-limit"],
}

# %% [markdown]
# <details><summary>💡 Hint 1 — what to think about</summary>
#
# Two categories can ask for the same mitigation on the same item. Should the checklist then carry one
# row or two, and what should the row say about who asked? And what is the right behaviour when a category
# has exposures and the catalogue has nothing for it?
#
# </details>
# <details><summary>💡 Hint 2 — the approach in words</summary>
#
# Build a mapping keyed by `(item, mitigation)` whose value is the set of categories that asked. Walk the
# register, raise for a category that has items and no entry, and add to the mapping. At the end sort the
# keys and turn each set into a sorted tuple.
#
# </details>

# %%
def mitigation_checklist(register, controls):
    """The mitigations each exposed item needs, merged across categories.

    Args:
        register: dict category -> sorted list of item ids (exercise 3).
        controls: dict category -> list of mitigation ids.

    A category with exposed items and no key in ``controls`` raises ``ValueError``. A key with an empty
    list is an entry (no rows, no error).

    Returns:
        A list of ``(item, mitigation, categories)`` tuples, sorted by item then mitigation, one per distinct
        pair; ``categories`` is the sorted tuple of every category that asks for that pair.

    Example:
        >>> mitigation_checklist({"ASI02": ["t"], "ASI03": ["t"]}, {"ASI02": ["a", "b"], "ASI03": ["b"]})
        [('t', 'a', ('ASI02',)), ('t', 'b', ('ASI02', 'ASI03'))]
    """
    # YOUR CODE HERE
    raise NotImplementedError


def _check_mitigation_checklist() -> None:
    reg = {"ASI02": ["t", "u"], "ASI03": ["t"], "ASI05": []}
    ctl = {"ASI02": ["a", "b"], "ASI03": ["b", "c"]}
    got = mitigation_checklist(reg, ctl)
    want = [("t", "a", ("ASI02",)), ("t", "b", ("ASI02", "ASI03")), ("t", "c", ("ASI03",)), ("u", "a", ("ASI02",)), ("u", "b", ("ASI02",))]
    assert [tuple(r) for r in got] == want, (
        f"got {[tuple(r) for r in got]}. One row per distinct (item, mitigation), sorted by item then mitigation; "
        "when two categories ask for the same pair the row says both, as a sorted tuple.")
    try:
        mitigation_checklist({"ASI09": ["h"]}, {"ASI02": ["a"]})
    except ValueError:
        pass
    else:
        raise AssertionError("a category with exposed items and no mitigation listed must raise ValueError")
    print("exercise 4 looks right")


_try("exercise 4", _check_mitigation_checklist)

# %%
def _show_checklist() -> None:
    reg = risk_register(COMPONENTS, FLOWS, tainted_components(COMPONENTS, FLOWS), RULES)
    rows = mitigation_checklist(reg, CONTROLS)
    naive = sum(len(items) * len(CONTROLS[asi]) for asi, items in reg.items())
    merged = [r for r in rows if len(r[2]) > 1]
    print(f"{naive} (item, category, mitigation) requests from the register become {len(rows)} checklist rows")
    print(f"{len(merged)} rows are asked for by more than one category: " + "; ".join(f"{i} / {m} ({', '.join(c)})" for i, m, c in merged))
    items = sorted({r[0] for r in rows})
    print(f"{len(items)} items carry work; the one with the most rows is {max(items, key=lambda i: sum(r[0] == i for r in rows))}")


