# %% [markdown]
# ## 6. Exercise 5 — `run_checks`: tests that fail when a mitigation is missing
#
# A checklist nobody runs is a document. Each mitigation here has a **checker**, a function
# `checker(arch, item) -> bool` that reads the item's configuration and says whether the mitigation is
# in place. The next cell gives them: read how each decides. A checker here is deliberately fragile, and a
# mitigation has no checker at all, because not everything can be tested yet.
#
# Write `run_checks(checklist, arch, checkers)` that runs the checker of every row and returns the failing
# rows as `(item, mitigation, reason)` in checklist order, with reason:
#
# * `"missing"`: the checker returned anything other than the exact value `True`;
# * `"error"`: the checker raised an `Exception`. A check that cannot run is not a pass: **fail closed**;
# * `"no checker"`: the mitigation is not a key of `checkers`.
#
# Catch `Exception`, not everything: the notebook's time limit must still be able to stop a checker.

# %%
def _cfg(arch, item):
    return arch["config"].get(item, {})


CHECKERS = {
    "untrusted-content-marked": lambda arch, item: _cfg(arch, item).get("wraps_untrusted") is True,
    "tool-allowlist": lambda arch, item: bool(_cfg(arch, item).get("allowed_tools")) and "*" not in _cfg(arch, item)["allowed_tools"],
    "argument-validation": lambda arch, item: _cfg(arch, item).get("schema_validated") is True,
    "human-approval-on-irreversible": lambda arch, item: _cfg(arch, item).get("approval") == "required",
    "scoped-credentials": lambda arch, item: (bool(_cfg(arch, item).get("scopes"))
                                              and not any("*" in s for s in _cfg(arch, item)["scopes"])),
    "short-lived-tokens": lambda arch, item: _cfg(arch, item).get("token_ttl_s", 10 ** 9) <= 3600,
    "pinned-tool-versions": lambda arch, item: _cfg(arch, item).get("version") not in (None, "latest") and bool(_cfg(arch, item).get("digest")),
    "tool-description-review": lambda arch, item: _cfg(arch, item).get("description_reviewed") is True,
    "sandboxed-execution": lambda arch, item: _cfg(arch, item).get("sandbox") == "container" and _cfg(arch, item).get("network") == "none",
    "memory-write-validation": lambda arch, item: _cfg(arch, item).get("validate_writes") is True,
    "memory-provenance-tags": lambda arch, item: _cfg(arch, item).get("provenance") is True,
    "message-authentication": lambda arch, item: _cfg(arch, item)["auth"] in ("mtls", "signed"),        # KeyError when never set
    "step-and-spend-limit": lambda arch, item: _cfg(arch, item).get("max_steps", 10 ** 9) <= 25 and _cfg(arch, item).get("max_usd", 10 ** 9) <= 5,
    "approval-shows-raw-source": lambda arch, item: _cfg(arch, item).get("show_source") is True,
    "kill-switch": lambda arch, item: _cfg(arch, item).get("kill_switch") is True,
    "action-logging": lambda arch, item: _cfg(arch, item).get("log") == "append-only",
    # "goal-lock-check" has no checker: nobody has a reliable automatic test for it yet.
}

# %%
def run_checks(checklist, arch, checkers):
    """Run every row's checker and return the rows that do not pass.

    Args:
        checklist: list of (item, mitigation, categories), as from exercise 4.
        arch: the architecture dict; passed to each checker unchanged.
        checkers: dict mitigation id -> function ``checker(arch, item)``.

    Returns:
        A list of ``(item, mitigation, reason)`` in checklist order for each row that failed: "no checker"
        when the mitigation has no entry in ``checkers``; "error" when the checker raised an ``Exception``;
        "missing" when it returned anything other than exactly ``True``. Passing rows are not listed.

    Example:
        >>> run_checks([("x", "m1", ()), ("x", "m2", ()), ("x", "m3", ())], {},
        ...            {"m1": lambda a, i: True, "m2": lambda a, i: 1 / 0})
        [('x', 'm2', 'error'), ('x', 'm3', 'no checker')]
    """
    # YOUR CODE HERE
    raise NotImplementedError


def _check_run_checks() -> None:
    rows = [("y", "m1", ()), ("x", "m2", ()), ("x", "m3", ()), ("y", "m4", ()), ("x", "m5", ()), ("x", "m6", ())]
    calls = []

    def seen(a, i):
        calls.append(i)
        return a == {"k": 1} and i in ("x", "y")
    ck = {"m1": seen, "m2": lambda a, i: {}["boom"], "m4": lambda a, i: "yes", "m5": lambda a, i: False, "m6": lambda a, i: 1}
    got = [tuple(r) for r in run_checks(rows, {"k": 1}, ck)]
    assert calls == ["y"], f"call checker(arch, item) exactly once per row, with the architecture you were given; got calls {calls}"
    assert got == [("x", "m2", "error"), ("x", "m3", "no checker"), ("y", "m4", "missing"), ("x", "m5", "missing"), ("x", "m6", "missing")], (
        f"got {got}. Only an exact True passes ('yes' is not True); a checker that raises is an 'error', not a pass and "
        "not a crash; a mitigation with no checker is 'no checker'; keep the checklist's order.")
    class _Halt(BaseException):
        """Stands in for the notebook's time limit, which is not an Exception either."""

    def halt(arch, item):
        raise _Halt()
    try:
        run_checks([("x", "h", ())], {}, {"h": halt})
    except _Halt:
        pass
    else:
        raise AssertionError("catch Exception, not BaseException: the time limit that protects this notebook must get through")
    print("exercise 5 looks right")


_try("exercise 5", _check_run_checks)

